import * as pdfjs from './vendor/pdf.mjs';
pdfjs.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;
export async function extractPDF(file,onProgress=()=>{},signal){if(file.size>50*1024*1024)throw Error('PDF 上限 50 MB');let bytes=new Uint8Array(await file.arrayBuffer());if(!new TextDecoder().decode(bytes.slice(0,1024)).includes('%PDF-'))throw Error('不是有效的 PDF');let task=pdfjs.getDocument({data:bytes,cMapUrl:new URL('./vendor/cmaps/',import.meta.url).href,cMapPacked:true,standardFontDataUrl:new URL('./vendor/standard_fonts/',import.meta.url).href,wasmUrl:new URL('./vendor/wasm/',import.meta.url).href,isEvalSupported:false});let doc;try{doc=await task.promise;if(doc.numPages>500)throw Error('單份 PDF 上限 500 頁，請先拆分');let pages=[];let labels=await doc.getPageLabels();for(let n=1;n<=doc.numPages;n++){if(signal?.aborted)throw new DOMException('已取消','AbortError');let page=await doc.getPage(n),content=await page.getTextContent();let text=content.items.filter(x=>'str'in x).map(x=>x.str+(x.hasEOL?'\n':' ')).join('').trim();pages.push({page:n,label:labels?.[n-1]||String(n),text});page.cleanup();onProgress(n,doc.numPages)}return pages}finally{await task.destroy()}}
